public class Main {
    static long[] keySums(int n, int[] parents, String[] kind, int[] a, long[] b) {
        // parents[i - 2] is the parent of initial key i (i = 2..n)
        // operation j: kind[j] is "Ro" (add key b[j] under a[j]) or "Re" (add b[j] at level a[j] and below)
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        int[] parents = new int[Math.max(0, n - 1)];
        for (int i = 0; i < n - 1; i++) parents[i] = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        String[] kind = new String[q];
        int[] a = new int[q];
        long[] b = new long[q];
        for (int j = 0; j < q; j++) {
            kind[j] = st.nextToken();
            a[j] = Integer.parseInt(st.nextToken());
            b[j] = Long.parseLong(st.nextToken());
        }
        long[] res = keySums(n, parents, kind, a, b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}

