def gen(rng):
    def make(n, q, tree_mode, maxl, zmax, ro_prob):
        parents = []
        lv = [0, 0]
        for i in range(2, n + 1):
            if tree_mode == 'chain':
                p = i - 1
            elif tree_mode == 'star':
                p = 1
            else:
                p = rng.randint(1, i - 1)
            parents.append(p)
            lv.append(lv[p] + 1)
        cnt = n
        ops = []
        for _ in range(q):
            if rng.random() < ro_prob:
                p = rng.randint(1, cnt) if tree_mode != 'chain' else cnt
                cnt += 1
                lv.append(lv[p] + 1)
                ops.append(f'Ro {p} {cnt}')
            else:
                l = rng.randint(0, maxl)
                ops.append(f'Re {l} {rng.randint(1, zmax)}')
        return f'{n}\n' + ' '.join(map(str, parents)) + f'\n{q}\n' + '\n'.join(ops)
